 d=out/name;d.mkdir();source=d/'source.zil';source.write_bytes((a.repo/'tests/language-readiness/task-owner-transport'/f'{name}.zil').read_bytes());cmd=[str(cli),'check',str(source),'--work-profile','standard','--emit-dir',str(d/'phases'),'--json'];r=subprocess.run(cmd,cwd=a.repo,capture_output=True,timeout=180);(d/'stdout.json').write_bytes(r.stdout);(d/'stderr.txt').write_bytes(r.stderr);v=json.loads(r.stdout);row={'case':name,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'command':cmd,'exit':r.returncode,'status':v.get('status'),'phase':v.get('phase'),'verification_runs':v.get('verification_runs'),'diagnostics':v.get('diagnostics'),'verified':r.returncode==0 and v.get('status')=='Success' and v.get('verification_runs')==1};(d/'receipt.json').write_text(json.dumps(row,indent=2)+'\n');compress_phases(d);print(name,row['status'],row['phase'],flush=True);return row
